onProfilesSelected(selectedProfiles) {
  // Store selected profiles for the current message
  const profileMentions = selectedProfiles.map(p => ({
    name: p.name,
    description: p.description,
    avatar: p.avatar,
    role: 'profile'
  }))

  // Update the mentions to include profiles
  this.mentions = this.mentions.filter(m => m.role !== 'profile')
  this.mentions = [...this.mentions, ...profileMentions]
}

getUserMessage({ message, task_item }) {
  return this.chatSvc.getUserMessage({
    message,
    files: this.chatSvc.getMessageFiles({ messageMentions: this.messageMentions, files: this.files }),
    profiles: this.chatSvc.getMessageProfiles({ messageMentions: this.messageMentions, selectedUser: this.selectedUser, currentUser: this.$user }),
    images: this.images,
    metadata: this.metadata,
    user: this.$user.username,
    task_item
  })
}

