<script>
export default {
  props: {
    profiles: {
      type: Array,
      default: () => []
    },
    selectedProfiles: {
      type: Array,
      default: () => []
    }
  },
  data() {
    return {
      internalSelected: []
    }
  },
  computed: {
    availableProfiles() {
      return this.profiles || []
    }
  },
  watch: {
    selectedProfiles: {
      handler(newVal) {
        this.internalSelected = newVal.map(p => typeof p === 'string' ? p : p.name)
      },
      deep: true
    }
  },
  mounted() {
    this.internalSelected = this.selectedProfiles.map(p => typeof p === 'string' ? p : p.name)
  },
  methods: {
    isProfileSelected(profileName) {
      return this.internalSelected.includes(profileName)
    },

    toggleProfile(profile) {
      const profileName = profile.name
      const index = this.internalSelected.indexOf(profileName)

      if (index > -1) {
        this.internalSelected.splice(index, 1)
      } else {
        this.internalSelected.push(profileName)
      }

      const updatedProfiles = this.availableProfiles.filter(p => 
        this.internalSelected.includes(p.name)
      )
      this.$emit('update:selected-profiles', updatedProfiles)
    }
  }
}
</script>
